    -- Initialize mob detection
    function Features.initializeMobDetection()
        local sharedState = {}
        local sharedState2 = {}
        local sharedState3 = {}
        Runtime.localPlayer2.CharacterAdded:Connect(Runtime.handler15)

        local handler = function(y, instance)
            local isWithinRange = Runtime.localPlayer2.Character and Runtime.localPlayer2.Character:FindFirstChild("HumanoidRootPart") and y and y:FindFirstChild("HumanoidRootPart") and y.Humanoid.Health > 0 and (Runtime.localPlayer2.Character.HumanoidRootPart.Position - y.HumanoidRootPart.Position).Magnitude < (instance or 70)
            if isWithinRange then
                if getgenv().SmartMob ~= y then
                    getgenv().SmartMob = y
                    getgenv().SmartHealth = y.Humanoid.Health
                    getgenv().SmartTime = tick()
                    instance = NameWeapon("Blox Fruit", true)
                    if instance and (string.find(instance.Name, "T-Rex") or string.find(instance.Name, "Kitsune") or string.find(instance.Name, "Leopard") or string.find(instance.Name, "Mammoth") or string.find(instance.Name, "Dough")) then
                        getgenv().YPosFruit = 7
                    else
                        getgenv().YPosFruit = 20
                    end
                elseif y.Humanoid.Health < getgenv().SmartHealth then
                    getgenv().SmartHealth = y.Humanoid.Health
                    getgenv().SmartTime = tick()
                elseif tick() - getgenv().SmartTime > 1.5 then
                    getgenv().YPosFruit = math.max(0, (getgenv().YPosFruit or 20) - 5)
                    getgenv().SmartTime = tick()
                end
            end
            return isWithinRange
        end

        getgenv().ClickM1 = function(inputValue, inputValue2, inputValue3)
            local numberValue
            if inputValue2 then
                numberValue = 250
            else
                numberValue = 70
            end
            if not handler(inputValue, numberValue) then
                return
            end
            do
                local character = Runtime.localPlayer2.Character
                if Runtime.localPlayer2.Character then
                    character = not Runtime.localPlayer2.Character:FindFirstChildOfClass("Tool")
                end
                local backpack = game:GetService("Players").LocalPlayer.Backpack
                character = character and (backpack:FindFirstChild("T-Rex-T-Rex") or backpack:FindFirstChild("Kitsune-Kitsune") or backpack:FindFirstChild("Leopard-Leopard") or backpack:FindFirstChild("Mammoth-Mammoth") or backpack:FindFirstChild("Dough-Dough"))
                if Settings["Select Weapon"] ~= "Blox Fruit" then
                    if character and getgenv().UseFruitM1(inputValue, nil, inputValue3) then
                        return
                    end
                elseif getgenv().UseFruitM1(inputValue, nil, inputValue3) then
                    return
                end
                local numberValue2
                if inputValue2 then
                    numberValue2 = 250
                else
                    numberValue2 = 30
                end
                AttackFunction(numberValue2)
                return
            end
        end

        getgenv().ClickM1Dungeon = function(inputValue, inputValue2)
            local character
            if handler then
                local numberValue
                if inputValue2 then
                    numberValue = 250
                else
                    numberValue = 70
                end
                if not handler(inputValue, numberValue) then
                    return
                end
                character = Runtime.localPlayer2.Character
                if Runtime.localPlayer2.Character then
                    character = not Runtime.localPlayer2.Character:FindFirstChildOfClass("Tool")
                end
            else
                character = not Runtime.localPlayer2.Character:FindFirstChildOfClass("Tool")
            end
            local backpack = game:GetService("Players").LocalPlayer.Backpack
            character = character and (backpack:FindFirstChild("T-Rex-T-Rex") or backpack:FindFirstChild("Kitsune-Kitsune") or backpack:FindFirstChild("Leopard-Leopard") or backpack:FindFirstChild("Mammoth-Mammoth") or backpack:FindFirstChild("Dough-Dough"))
            if Settings["Select Weapon Dungeon"] ~= "Blox Fruit" then
                if character and getgenv().UseFruitM1(inputValue) then
                    return
                end
            elseif getgenv().UseFruitM1(inputValue) then
                return
            end
            local numberValue
            if inputValue2 then
                numberValue = 250
            else
                numberValue = 30
            end
            AttackFunction(numberValue)
        end

        getgenv().ClickM1Volcano = function(inputValue, inputValue2)
            local numberValue
            if inputValue2 then
                numberValue = 250
            else
                numberValue = 70
            end
            if not handler(inputValue, numberValue) then
                return
            end
            do
                local character = Runtime.localPlayer2.Character
                if Runtime.localPlayer2.Character then
                    character = not Runtime.localPlayer2.Character:FindFirstChildOfClass("Tool")
                end
                local backpack = game:GetService("Players").LocalPlayer.Backpack
                character = character and (backpack:FindFirstChild("T-Rex-T-Rex") or backpack:FindFirstChild("Kitsune-Kitsune") or backpack:FindFirstChild("Leopard-Leopard") or backpack:FindFirstChild("Mammoth-Mammoth") or backpack:FindFirstChild("Dough-Dough"))
                local value, numberValue2
