        function DetectPartMobBring(y, inputValue, inputValue2, targetRoot)
            local data, x = {}, if string.find(y, "Lv.") then y:gsub(" %pLv. %d+%p", "") else nil
            for k, value in pairs(TableMobSpawn) do
                k = if string.find(value.Name, "Lv.") then value.Name:gsub(" %pLv. %d+%p", "") else nil
                if value:IsA("Part") then
                    if k and k == y then
                        table.insert(data, value)
                    elseif y == value.Name then
                        table.insert(data, value)
                    elseif x and value.Name == x then
                        table.insert(data, value)
                    end
                end
            end
            if inputValue2 then
                local numberValue, x = 1 / 0
                for k, value in next, data, nil do
                    k = (inputValue.HumanoidRootPart.Position - value.Position).Magnitude
                    if numberValue > (inputValue.HumanoidRootPart.Position - value.Position).Magnitude then
                        numberValue, x = (inputValue.HumanoidRootPart.Position - value.Position).Magnitude, value
                    end
                end
                return x
            else
                y = {}
                for k, value in next, data, nil do
                    if (targetRoot.Position - value.Position).Magnitude <= 200 then
                        table.insert(y, value)
                    end
                end
                if not (#y < #data) then
                    return
                end
                do
                    return true
                end
            end
        end

