        function BringMob(instance)
            if not Settings["Bring Mob"] then
                return
            end
            if instance and sharedState6.value ~= instance then
                sharedState6.value = instance
                sharedState7.value = DetectPartMobBring(instance.Name, instance, true).CFrame
