                    sharedState7.value = getcenter(instance.Name)
                end
                DeleteIgnoredMob()
            end
            if DaBringMob then
                delay(0.1, function()
                    getgenv().DaBringMob = false
                end)
                return
            end
            local data = {}
            if not (instance:FindFirstChild("Ignored")) then
                table.insert(data, instance)
            end
            local x = Settings["Bring Mob Count"] or 2
            local numberValue, numberValue2 = if (Settings["Bring Mob Count"] or 2) > 2 then 350 else 200
            if game:GetService("Players").LocalPlayer.Data.Race.Value == "Cyborg" then
