                numberValue2 = x
            end
            local value, value2 = pairs, table.pack(workspace.Enemies:GetChildren())
            for k, value3 in value((function(inputValue)
                return table.unpack(inputValue, 1, inputValue.n)
            end)(value2)) do
                if value3 ~= instance and (value3.Name == instance.Name and (not (value3:FindFirstChild("Ignored")) and (IsMobAlive(value3) and (isnetworkowner2(value3.HumanoidRootPart) and ((value3.HumanoidRootPart.Position - sharedState7.value.Position).Magnitude <= numberValue and #data < numberValue2))))) then
